<script setup lang="ts">import {whatsapp,track} from '~/utils/business';defineProps<{product:any}>();const {ar,c}=useCopy();const lp=useLocalePath()
</script><template><article class="product-card reveal"><NuxtLink :to="lp('/collections/'+product.slug)" class="product-image"><NuxtImg format="webp" v-if="!product.isSample" :src="product.image" :alt="product.name[ar?'ar':'en']" width="620" height="790" sizes="sm:90vw md:45vw lg:25vw" loading="lazy"/><div v-else class="sample-image"><span>✦</span>{{c('نموذج للتشكيلة','Collection preview')}}</div><UiBadge v-if="product.brand">{{product.brand==='lamees'?'Lamees':product.brand==='top-clas'?'Top Clas':'Baby 4 You'}}</UiBadge></NuxtLink><div class="product-meta"><span>{{product.code}}</span><span>{{product.ageRange?.[ar?'ar':'en']||c('استفسر عن المقاسات','Ask about sizes')}}</span></div><h3><NuxtLink :to="lp('/collections/'+product.slug)">{{product.name[ar?'ar':'en']}}</NuxtLink></h3><a class="product-quote" :href="whatsapp(c('مرحباً، أريد عرض سعر بالجملة لـ '+product.name.ar+' (رمز: '+product.code+')','Hello, I would like a wholesale quote for '+product.name.en+' (code: '+product.code+').'))" @click="track('whatsapp_click',{product:product.code})"><UiIcon name="whatsapp"/>{{c('طلب عرض سعر بالجملة','Request wholesale quote')}} </a></article></template>
